//!
//! Some warnings are emitted repeatedly for the same underlying condition and
//! clutter the transcript. In particular, the "model metadata not found"
//! warning can fire many times for the same model slug. `WarningDisplayState`
//! remembers which such slugs have already been shown so that only the first
//! occurrence per slug is added to history; all other warnings are always
//! displayed.

use std::collections::HashSet;

/// Prefix of the model-metadata warning, up to (and including) the opening
/// backtick that precedes the model slug.
const MODEL_METADATA_WARNING_PREFIX: &str = "Model metadata for `";
/// Suffix of the model-metadata warning, starting with the backtick that
/// follows the model slug.
const MODEL_METADATA_WARNING_SUFFIX: &str =
    "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

/// Tracks which warnings have already been displayed so repeated,
/// model-specific metadata warnings can be deduplicated.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs for which a metadata warning has already been shown.
    seen_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Decide whether `message` should be added to the chat history.
    ///
    /// For model-metadata warnings, returns `true` the first time a given slug
    /// is seen and `false` for every subsequent occurrence of the same slug.
    /// All other warnings always return `true`.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match extract_model_metadata_slug(message) {
            Some(slug) => self.seen_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// Extract the model slug from a model-metadata warning, if `message` matches
/// the exact pattern.
fn extract_model_metadata_slug(message: &str) -> Option<&str> {
    message
        .strip_prefix(MODEL_METADATA_WARNING_PREFIX)?
        .strip_suffix(MODEL_METADATA_WARNING_SUFFIX)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn metadata_warning(slug: &str) -> String {
        format!(
            "Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues."
        )
    }

